def load_json(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"无法读取 JSON 文件 {path}: {exc}") from exc
    if not isinstance(value, dict) or not value:
        raise ValueError(f"JSON 文件必须包含非空对象：{path}")
    return value


def draw_number(mode: str, low: float, high: float, mean: float, std: float) -> float:
    if low > high:
        raise ValueError("最小值不能大于最大值")
    if mode == "uniform":
        return random.uniform(low, high)
    if std <= 0:
        return min(high, max(low, mean))
    for _ in range(1000):
        sample = random.gauss(mean, std)
        if low <= sample <= high:
            return sample
    return min(high, max(low, mean))


def draw_count(mode: str, low: int, high: int, mean: float, std: float) -> int:
    return int(round(draw_number(mode, low, high, mean, std)))


CONFIG_FIELD_SPEC = {
    "star_system_count": (("star_system", "count"), "integer"),
    "star_system_position_range": (("star_system", "position", "range"), "number"),
    "minimum_star_system_distance": (("star_system", "position", "minimum_distance"), "number"),
    "minimum_planet_orbit_radius": (("planet_orbit_radius", "minimum"), "number"),
    "maximum_planet_orbit_radius": (("planet_orbit_radius", "maximum"), "number"),
    "planet_orbit_radius_distribution": (("planet_orbit_radius", "distribution"), "distribution"),
    "planet_orbit_radius_mean": (("planet_orbit_radius", "mean"), "number"),
    "planet_orbit_radius_standard_deviation": (("planet_orbit_radius", "standard_deviation"), "number"),
    "minimum_planet_count_per_system": (("planet_count", "minimum"), "integer"),
    "maximum_planet_count_per_system": (("planet_count", "maximum"), "integer"),
    "planet_count_distribution": (("planet_count", "distribution"), "distribution"),
    "planet_count_mean": (("planet_count", "mean"), "number"),
    "planet_count_standard_deviation": (("planet_count", "standard_deviation"), "number"),
    "minimum_planet_orbit_spacing": (("orbit_spacing", "minimum_between_planets"), "number"),
    "minimum_moon_orbit_spacing": (("orbit_spacing", "minimum_between_moons"), "number"),
    "minimum_celestial_body_radius": (("celestial_body_radius", "minimum"), "number"),
    "maximum_celestial_body_radius": (("celestial_body_radius", "maximum"), "number"),
    "celestial_body_radius_distribution": (("celestial_body_radius", "distribution"), "distribution"),
    "celestial_body_radius_mean": (("celestial_body_radius", "mean"), "number"),
    "celestial_body_radius_standard_deviation": (("celestial_body_radius", "standard_deviation"), "number"),
    "resource_position_range": (("surface_resource", "position", "range"), "number"),
    "resource_total_count_distribution": (("surface_resource", "totalcount", "distribution"), "distribution"),
    "resource_total_count_mean": (("surface_resource", "totalcount", "mean"), "number"),
    "resource_total_count_standard_deviation": (("surface_resource", "totalcount", "standard_deviation"), "number"),
    "resource_reserves_distribution": (("surface_resource", "reserves", "distribution"), "distribution"),
    "resource_reserves_mean": (("surface_resource", "reserves", "mean"), "number"),
    "resource_reserves_standard_deviation": (("surface_resource", "reserves", "standard_deviation"), "number"),
    "star_type_file": (("files", "star_types"), "path"),
    "planet_type_file": (("files", "planet_types"), "path"),
    "resource_type_file": (("files", "resource_types"), "path"),
    "item_file": (("files", "items"), "path"),
    "output_file": (("files", "output"), "path"),
    "random_seed": (("random_seed",), "optional_integer"),
}


def config_leaf_paths(value: Any, prefix: tuple[str, ...] = ()) -> set[tuple[str, ...]]:
    if not isinstance(value, dict) or not value:
        return {prefix}
    return set().union(*(config_leaf_paths(child, prefix + (key,)) for key, child in value.items()))


def load_config(path: Path) -> argparse.Namespace:
    config = load_json(path)
    expected = {field_path for field_path, _ in CONFIG_FIELD_SPEC.values()}
    actual = config_leaf_paths(config)
    missing = expected - actual
    extra = actual - expected
    if missing or extra:
        format_paths = lambda paths: sorted(".".join(parts) for parts in paths)
        raise ValueError(f"配置文件字段不匹配：缺少 {format_paths(missing)}；未知 {format_paths(extra)}")

    values: dict[str, Any] = {}
    for field, (field_path, kind) in CONFIG_FIELD_SPEC.items():
        value: Any = config
        for part in field_path:
            value = value[part]
        location = ".".join(field_path)
        if kind == "number":
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
                raise ValueError(f"配置项 {location} 必须是有限数字")
        elif kind == "integer":
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError(f"配置项 {location} 必须是整数")
        elif kind == "optional_integer":
            if value is not None and (isinstance(value, bool) or not isinstance(value, int)):
                raise ValueError(f"配置项 {location} 必须是整数或 null")
        elif kind == "distribution":
            if not isinstance(value, str) or value not in {"uniform", "normal", "均匀分布", "正态分布"}:
                raise ValueError(f"配置项 {location} 必须是 uniform 或 normal")
            value = {"均匀分布": "uniform", "正态分布": "normal"}.get(value, value)
        elif kind == "path":
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f"配置项 {location} 必须是非空路径字符串")
            value = Path(value)
            if not value.is_absolute():
                value = ROOT / value
        values[field] = value

    if values["random_seed"] is not None:
        random.seed(values["random_seed"])
    return argparse.Namespace(**values)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="从 JSON 配置生成 spaceMap.json")
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG, help="配置文件路径，默认 scripts/space_map_config.json")
    cli = parser.parse_args()
    return load_config(cli.config)


def validate(
    args: argparse.Namespace,
    star_types: dict[str, Any],
    planet_types: dict[str, Any],
    resource_types: dict[str, Any],
    items: dict[str, Any],
) -> None:
    if args.star_system_count < 1 or args.star_system_position_range <= 0 or args.minimum_star_system_distance < 0:
        raise ValueError("star_system_count 和 star_system_position_range 必须大于 0，minimum_star_system_distance 不能小于 0")
    if args.star_system_count > len(SYSTEM_NAME_LIBRARY):
        raise ValueError(f"名称库共有 {len(SYSTEM_NAME_LIBRARY)} 个恒星系，star_system_count 不能超过名称库数量")
    if args.minimum_planet_orbit_radius < 0 or args.maximum_planet_orbit_radius < args.minimum_planet_orbit_radius or args.minimum_planet_orbit_spacing < 0 or args.minimum_moon_orbit_spacing < 0:
        raise ValueError("行星轨道半径范围或最小轨道间距无效")
    if args.minimum_planet_count_per_system < 0 or args.maximum_planet_count_per_system < args.minimum_planet_count_per_system:
        raise ValueError("minimum_planet_count_per_system/maximum_planet_count_per_system 无效")
    if args.maximum_planet_count_per_system > 1 and args.minimum_planet_orbit_spacing * (args.maximum_planet_count_per_system - 1) > args.maximum_planet_orbit_radius - args.minimum_planet_orbit_radius:
        raise ValueError("行星数量上限和 minimum_planet_orbit_spacing 超出可用轨道范围")
    if args.minimum_celestial_body_radius < 0 or args.maximum_celestial_body_radius < args.minimum_celestial_body_radius:
        raise ValueError("行星半径范围无效")
    if args.resource_position_range < 0:
        raise ValueError("resource_position_range 不能小于 0")
    if args.resource_total_count_mean < 0 or args.resource_total_count_standard_deviation < 0:
        raise ValueError("surface_resource.totalcount 的 mean 和 standard_deviation 不能小于 0")
    if args.resource_reserves_mean < 0 or args.resource_reserves_standard_deviation < 0:
        raise ValueError("surface_resource.reserves 的 mean 和 standard_deviation 不能小于 0")
    if not star_types or not planet_types:
        raise ValueError("starType.json 和 planetType.json 至少需要一个类型")
    if not resource_types:
        raise ValueError("resourceType.json 中没有可选资源类型")
    for label, obj in (("starType", star_types), ("planetType", planet_types)):
        for key, value in obj.items():
            if not isinstance(value, dict) or not isinstance(value.get("displayName"), str):
                raise ValueError(f"{label} 条目 {key!r} 缺少 displayName")
    for planet_type_id, planet_type in planet_types.items():
        resources = planet_type.get("resource")
        if not isinstance(resources, dict):
            raise ValueError(f"planetType {planet_type_id!r} 的 resource 必须是对象")
        for item_id, details in resources.items():
            if item_id not in items:
                raise ValueError(f"planetType {planet_type_id!r} 引用了 item.json 中不存在的物品 {item_id!r}")
            if not isinstance(details, dict):
                raise ValueError(f"planetType {planet_type_id!r} 的资源 {item_id!r} 必须是对象")
            for field in ("abundanceMean", "reservesMean"):
                value = details.get(field)
                if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
                    raise ValueError(f"planetType {planet_type_id!r} 的资源 {item_id!r}.{field} 必须是非负有限数字")


def make_positions(count: int, extent: float, min_distance: float) -> list[dict[str, float]]:
    points: list[tuple[float, float]] = []
    for _ in range(count):
        for _attempt in range(100_000):
            point = (random.uniform(-extent, extent), random.uniform(-extent, extent))
            if all(math.dist(point, existing) >= min_distance for existing in points):
                points.append(point)
                break
        else:
            raise ValueError("给定 star_system_position_range 和 minimum_star_system_distance 无法放置所需数量的恒星系")
    return [{"x": round(x, 4), "y": round(y, 4)} for x, y in points]


def draw_deviations(distribution: str, standard_deviation: float, count: int) -> list[float]:
    """Draw a batch of zero-mean offsets with the requested absolute standard deviation."""
    if standard_deviation == 0:
        return [0.0] * count
    if distribution == "normal":
        return [random.gauss(0, standard_deviation) for _ in range(count)]
    half_width = math.sqrt(3) * standard_deviation
    return [random.uniform(-half_width, half_width) for _ in range(count)]


def make_surface_resources(
    args: argparse.Namespace,
    resource_types: dict[str, Any],
    planet_resources: dict[str, dict[str, float]],
) -> list[dict[str, Any]]:
    resource_settings = list(planet_resources.items())
    if not resource_settings:
        return []

    count_deviations = draw_deviations(
        args.resource_total_count_distribution,
        args.resource_total_count_standard_deviation,
        len(resource_settings),
    )
    point_settings: list[tuple[str, float]] = []
    for (item_id, settings), deviation in zip(resource_settings, count_deviations):
        expected_count = settings["abundanceMean"] * args.resource_total_count_mean
        point_count = max(0, round(expected_count + deviation))
        expected_reserves = settings["reservesMean"] * args.resource_reserves_mean
        point_settings.extend([(item_id, expected_reserves)] * point_count)

    reserves_deviations = draw_deviations(
        args.resource_reserves_distribution,
        args.resource_reserves_standard_deviation,
        len(point_settings),
    )
    resource_type_ids = list(resource_types)
    return [
        {
            "resourceType": random.choice(resource_type_ids),
            "item": item_id,
            "position": {
                "x": round(random.uniform(0, args.resource_position_range), 3),
                "y": round(random.uniform(0, args.resource_position_range), 3),
            },
            "reserves": max(0.0, round(expected_reserves + deviation, 2)),
        }
        for (item_id, expected_reserves), deviation in zip(point_settings, reserves_deviations)
    ]


def sample_orbits(args: argparse.Namespace, count: int) -> list[float]:
    if count == 0:
        return []
    if count == 1:
        return [round(draw_number(args.planet_orbit_radius_distribution, args.minimum_planet_orbit_radius, args.maximum_planet_orbit_radius, args.planet_orbit_radius_mean, args.planet_orbit_radius_standard_deviation), 5)]
    available = args.maximum_planet_orbit_radius - args.minimum_planet_orbit_radius
    if args.minimum_planet_orbit_spacing * (count - 1) > available:
        raise ValueError("当前行星数要求的最小轨道间距超出行星轨道半径范围")
    for _ in range(500):
        values = sorted(draw_number(args.planet_orbit_radius_distribution, args.minimum_planet_orbit_radius, args.maximum_planet_orbit_radius, args.planet_orbit_radius_mean, args.planet_orbit_radius_standard_deviation) for _ in range(count))
        if all(b - a >= args.minimum_planet_orbit_spacing for a, b in zip(values, values[1:])):
            return [round(value, 5) for value in values]
    # Deterministic safe fallback when a narrow normal distribution makes rejection unlikely.
    step = available / (count - 1)
    if step < args.minimum_planet_orbit_spacing:
        raise ValueError("轨道范围不足以满足 minimum_planet_orbit_spacing")
    return [round(args.minimum_planet_orbit_radius + i * step, 5) for i in range(count)]


def make_body(
    key: str,
    name: str,
    kind: str,
    orbital_radius: float,
    args: argparse.Namespace,
    resource_types: dict[str, Any],
    planet_resources: dict[str, dict[str, float]],
) -> dict[str, Any]:
    # Orbital periods are stored in days; game code can convert to seconds for display.
    period_days = 365.25 * math.sqrt(max(orbital_radius, 0.000001) ** 3)
    return {
        "displayName": name,
        "planetType": kind,
        "position": {
            "orbitalRadius": round(orbital_radius, 5),
            "orbitalPeriod": round(period_days, 5),
            "radius": round(draw_number(args.celestial_body_radius_distribution, args.minimum_celestial_body_radius, args.maximum_celestial_body_radius, args.celestial_body_radius_mean, args.celestial_body_radius_standard_deviation), 2),
        },
        "surface": {"resource": make_surface_resources(args, resource_types, planet_resources)},
        "planet": {},
    }


def iter_systems(args: argparse.Namespace) -> Iterator[tuple[str, dict[str, Any]]]:
    stars = load_json(args.star_type_file)
    planets = load_json(args.planet_type_file)
    resource_types = load_json(args.resource_type_file)
    all_items = load_json(args.item_file)
    validate(args, stars, planets, resource_types, all_items)
    positions = make_positions(args.star_system_count, args.star_system_position_range, args.minimum_star_system_distance)
    star_keys = list(stars)
    planet_keys = list(planets)
    selected_groups = random.sample(list(SYSTEM_NAME_LIBRARY.items()), args.star_system_count)

    for system_index, (star_key, name_group) in enumerate(selected_groups):
        star_name = name_group["displayName"]
        star_type = random.choice(star_keys)
        planet_count = min(
            draw_count(args.planet_count_distribution, args.minimum_planet_count_per_system, args.maximum_planet_count_per_system, args.planet_count_mean, args.planet_count_standard_deviation),
            len(name_group["planets"]),
        )
        orbits = sample_orbits(args, planet_count)
        system_planets: dict[str, Any] = {}
        chosen_planets = random.sample(list(name_group["planets"].items()), planet_count)
        for planet_index, orbit in enumerate(orbits):
            planet_key, planet_name = chosen_planets[planet_index]
            planet_type = random.choice(planet_keys)
            body = make_body(planet_key, planet_name, planet_type, orbit, args, resource_types, planets[planet_type]["resource"])

            left_gap = orbit - orbits[planet_index - 1] if planet_index else math.inf
            right_gap = orbits[planet_index + 1] - orbit if planet_index + 1 < planet_count else math.inf
            nearest_gap = min(left_gap, right_gap)
            # Keep each moon at least one planet-spacing unit from its parent.
            # The half-gap bound also keeps it that far from neighboring planets.
            moon_min = max(0.0001, args.minimum_planet_orbit_spacing)
            moon_max = min(10.0, nearest_gap / 2) if math.isfinite(nearest_gap) else 10.0
            requested_moons = random.randint(0, 2) if moon_max >= moon_min else 0
            moon_capacity = 0 if moon_max < moon_min else 1 + int((moon_max - moon_min) // args.minimum_moon_orbit_spacing) if args.minimum_moon_orbit_spacing > 0 else requested_moons
            moon_count = min(requested_moons, moon_capacity)
            moons: dict[str, Any] = {}
            moon_orbits: list[float] = []
            if moon_count == 1:
                moon_orbits = [random.uniform(moon_min, moon_max)]
            elif moon_count > 1:
                for _ in range(500):
                    candidate = sorted(random.uniform(moon_min, moon_max) for _ in range(moon_count))
                    if all(b - a >= args.minimum_moon_orbit_spacing for a, b in zip(candidate, candidate[1:])):
                        moon_orbits = candidate
                        break
                if not moon_orbits:
                    span = moon_max - moon_min
                    step = span / (moon_count - 1)
                    moon_orbits = [moon_min + i * step for i in range(moon_count)]
            for moon_index in range(moon_count):
                moon_key = f"Moon{moon_index + 1:02d}"
                moon_name = f"{planet_name}·卫星 {moon_index + 1}"
                moon_orbit = moon_orbits[moon_index]
                moon_type = random.choice(planet_keys)
                moon = make_body(
                    moon_key,
                    moon_name,
                    moon_type,
                    moon_orbit,
                    args,
                    resource_types,
                    planets[moon_type]["resource"],
                )
                # A compact game-scale lunar orbit usually completes in several days.
                moon["position"]["orbitalPeriod"] = round(random.uniform(1, 60), 5)
                moons[moon_key] = moon
            body["planet"] = moons
            system_planets[planet_key] = body

        yield star_key, {
            "displayName": star_name,
            "starType": star_type,
            "position": positions[system_index],
            "surface": {},
            "planet": system_planets,
        }


def generate(args: argparse.Namespace) -> dict[str, Any]:
    return dict(iter_systems(args))


def write_space_map(args: argparse.Namespace) -> tuple[int, int, int]:
    args.output_file.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        mode="w", encoding="utf-8", dir=args.output_file.parent,
        prefix=".spaceMap-", suffix=".tmp", delete=False,
    ) as temporary_file:
        temporary_path = Path(temporary_file.name)
        try:
            temporary_file.write("{\n")
            system_count = planet_count = moon_count = 0
            for star_key, system in iter_systems(args):
                if system_count:
                    temporary_file.write(",\n")
                temporary_file.write("  ")
                temporary_file.write(json.dumps(star_key, ensure_ascii=False))
                temporary_file.write(": ")
                json.dump(system, temporary_file, ensure_ascii=False, separators=(",", ":"))
                system_count += 1
                planet_count += len(system["planet"])
                moon_count += sum(len(body["planet"]) for body in system["planet"].values())
            temporary_file.write("\n}\n")
        except BaseException:
            temporary_file.close()
            temporary_path.unlink(missing_ok=True)
            raise
    try:
        temporary_path.replace(args.output_file)
    except OSError:
        temporary_path.unlink(missing_ok=True)
        raise
    return system_count, planet_count, moon_count


def main() -> int:
    try:
        args = parse_args()
        systems, planets, moons = write_space_map(args)
    except (OSError, ValueError) as exc:
        print(f"错误：{exc}", file=sys.stderr)
        return 2
    print(f"已生成 {args.output_file}：{systems} 个恒星系、{planets} 颗行星、{moons} 颗卫星")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
